cat > app/api/v3/account/data-export/route.ts <<'EOF'
/**
 * GET /api/v3/account/data-export - the signed-in user's own personal data, for the "Download my data"
 * button on the profile settings page.
 *
 * Session-only, deliberately: the export is about the person behind the browser session, so an API key
 * (which acts for a workspace, not a person) has nothing to export and is refused with 401.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { getV3SessionUserId } from "@/app/api/v3/lib/auth";
import { problemUnauthorized } from "@/app/api/v3/lib/response";
import { exportV3AccountData } from "./lib/operations";

export const GET = withV3ApiWrapper({
  auth: "session",
  handler: async ({ authentication, requestId, instance }) => {
    const userId = getV3SessionUserId(authentication);
    if (!userId) return problemUnauthorized(requestId, "Not authenticated", instance);

    return exportV3AccountData({ userId, requestId, instance });
  },
});
EOF
cat > app/api/v3/account/data-export/lib/operations.ts <<'EOF'
import "server-only";
import { prisma } from "@formbricks/database";
import { problemNotFound, successResponse } from "@/app/api/v3/lib/response";
import { serializeV3AccountDataExport } from "../serializers";

/**
 * Scoped by the session's user id, never by a client-supplied one, so a caller can only ever read their
 * own row. Only accepted memberships are exported: a pending one is an invitation, not a membership yet.
 */
export async function exportV3AccountData(params: {
  userId: string;
  requestId: string;
  instance?: string;
}): Promise<Response> {
  const { userId, requestId, instance } = params;

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      name: true,
      email: true,
      locale: true,
      notificationSettings: true,
      memberships: {
        where: { accepted: true },
        select: { role: true, organization: { select: { name: true } } },
      },
    },
  });

  if (!user) return problemNotFound(requestId, "User", userId, instance);

  return successResponse(serializeV3AccountDataExport(user), { requestId });
}
EOF
cat > app/api/v3/account/data-export/serializers.ts <<'EOF'
export type TV3AccountDataExport = {
  name: string;
  email: string;
  locale: string;
  notificationSettings: unknown;
  organizationMemberships: { organizationName: string; role: string }[];
};

type TAccountDataUser = {
  name: string;
  email: string;
  locale: string;
  notificationSettings: unknown;
  memberships: { role: string; organization: { name: string } }[];
};

export const serializeV3AccountDataExport = (user: TAccountDataUser): TV3AccountDataExport => ({
  name: user.name,
  email: user.email,
  locale: user.locale,
  notificationSettings: user.notificationSettings,
  organizationMemberships: user.memberships.map((membership) => ({
    organizationName: membership.organization.name,
    role: membership.role,
  })),
});
EOF
